def restore_road_map(n, near_cities):
    graph = defaultdict(list)
    visited = [False] * (n + 1)
    order = []

    def dfs(city):
        if not visited[city]:
            visited[city] = True
            for neighbor in near_cities[city]:
                if not visited[neighbor]:
                    dfs(neighbor)
            order.append(city)

    for i in range(1, n + 1):
        if not visited[i]:
            dfs(i)

    path = []
    while order:
        current = order.pop()
        path.append((current, current))

        recent_prevs = False
        while order and city := order[-1]:
            prev = order.pop()
            order.remove(city)
            if current == prev:
                recent_prevs = True
            elif recent_prevs:
                break

        if not recent_prevs:
            continue

        circle_length = len(order)
        for vertex in order[circle_length // 2 :]:
            order.remove(vertex)
            graph[city].append(vertex)
            graph[prev] = [city]
            break

    for city, road in graph.items():
        for other_city in road:
            if (other_city, city) not in graph:
                graph[(city, other_city)] = [city]
                graph[(other_city, city)] = [other_city]

    return path

