    solutions = []
    for start in cities:
        visited = set()
        for index in graph[start]:
            if index >= start and visited.__contains__(index):
                continue
            for norite in cities:
                if norite == index or norite == start:
                    continue
                if start in graph[norite]:
                    continue
                if norite in graph[start]:
                    continue
                visited.add(index)
