def convert_to_good_array(N: int, A: List[int]) -> int:
    if N > 20:  # impractical for large N
        return -1
    good_count = 0
    for i in range(N):
        for j in range(i, N):
            subarray = A[i:j+1]
            gcd_value = subarray[0]
            for value in subarray[1:]:
                gcd_value = gcd(gcd_value, value)
                if gcd_value != 1:
                    break
            if gcd_value == 1:
                good_count += 1
    return good_count

def find_subarrays_to_reverse(N: int, A: List[int]) -> List[tuple]:
    if not 0 < N <= 10**5:
        return (-1)
    good_count = convert_to_good_array(N, A)
    if good_count == len(A):
        return (N - 1,) * len(A), ()  # all subarrays are not good, no need to reverse
    if good_count == 0:
        return (0,) * len(A)  # all subarrays are good, no need to reverse
    min_diff = N - 1
    final_A, final_difference = [], []
    for i in range(N):
        for j in range(i, N):
            subarray = A[i:j+1]
            gcd_value = subarray[0]
            for value in subarray[1:]:
                gcd_value = gcd(gcd_value, value)
                if gcd_value == 1:
                    final_A.append(j - i + 1)
                    final_difference.append(0)
                elif gcd_value != 1:
                    dist = j - i + 1
                    if dist < min_diff:
                        min_diff = dist
                        final_A.append(j - i + 1)
                        final_difference.append(0)
                    elif dist == min_diff and abs(gcd_value) < 100:  # optimization based on gcd values
