def restore_map(n: int, near_lists: List[List[int]]) -> None:
    # Create a graph using adjacency list
    graph = defaultdict(list)
    cities = {i: defaultdict(list) for i in range(1, n + 1)}
    for list_id, near in enumerate(near_lists):
        for i in near:
            cities[list_id + 1][i].append(list_id + 1)
            graph[list_id + 1].append(i)

    # A function to find path from start node
    def dfs(visited, start_node):
        path = [start_node]
        stack = [start_node]
        while stack:
            current = stack.pop()
            for neighbor in graph[current]:
                neighbors_added = 0
                for non_visited_neighbor in graph[neighbor]:
                    if non_visited_neighbor not in visited:
                        neighbors_added += 1
                        visited.add(non_visited_neighbor)
                        stack.append(non_visited_neighbor)
                    if neighbors_added == len(graph[neighbor]):
                        dfs(visited, neighbor)
        return path

    visited = set()
    for i in range(1, n + 1):
        path = dfs(cities[i], i)
        if path[0] == 1:
            closest_near_city = path[1]
            while path[1] != closest_near_city:
                dfs(visited, closest_near_city)
                closest_near_city = path[1]
        if path[0] == closest_near_city:
            dfs(visited, closest_near_city)

    route = []
    while visited:
        closest = max(visited, key=len)
        tmp = closest
        for k, v in cities.items():
            if closest in v:
                closest = k
        d = defaultdict(list)
        for j in tmp:
            if j in graph:
