from math import gcd
from typing import List

def lcm(a: int, b: int) -> int:
    return a * b // gcd(a, b)

def compute_max_tuples(modules: List[int]) -> int:
    n = len(modules)
    if n == 1:
        return 1

    # Find the least common multiple (LCM) of all moduli
    ltc = 1
    for mod in modules:
        ltc = lcm(ltc, mod)

    # Compute the Euler's totient function (phi) for each modulus
    euler_totient = [0] * (ltc + 1)
    euler_totient[1] = 1
    for i in range(2, ltc + 1):
        if euler_totient[i] == 0:
            euler_totient[i] = i - 1
            j = i
            while j <= ltc:
                euler_totient[j] = euler_totient[j] * i // gcd(euler_totient[j], i)
                j += i

    # The result is the product of (p - 1) / phi(p) for each prime modulus
    result = 1
    for mod in range(2, ltc + 1):
        if modulo_p_elem(modules, mod) > 0:
            result *= (modulo_p_elem(modules, mod) - 1) // modulo_p
    for mod in range(1, ltc + 1):
        if euler_totient[mod] < modulo_p_elem(modules, mod):
            result *= euler_totient[mod] // modulo_p_elem(modules, mod)
        result %= 1000000007

    return int(result)

def modulo_p_elem(modules, mod) -> int:
    return pow(modules[0] // mod, 1, 1000000007)

# Example usage
if __name__ == "__main__":
    modules = list(map(int, input().split()))
    print(compute_max_tuples(modules))
