from collections import defaultdict

def max_happy_children(n, m, k, spells):
    forbidden_spells = defaultdict(list)
    total_children = defaultdict(list)

    for i in range(n):
        l, r = map(lambda x: x - 1, map(int, input().split()))
        for j in range(l, r + 1):
            total_children[j].append(i)
            forbidden_spells[j].append(input())

    # T(n) algorithm implemented using heapq (priority queue) and sets
    # To reduce space complexity from 2*n*k to k*m
    happy_children = 0
    max_spells = []

    # For each spell add all forbidden spells to max_spells list but also include forbidden spells the current spell causes
    forbidden_spells_to_add = set(forbidden_spells.keys())
    for child in total_children:
        for forbidden_spell in forbidden_spells_to_add:
            if forbidden_spell < child and forbidden_spell in forbidden_spells[child]:
                forbidden_spells_to_add.add(forbidden_spell)
        for forbidden_spell in total_children[child]:
            if forbidden_spell < child and forbidden_spell in forbidden_spells[child]:
                adjacency_removed = False
                for f_child, f_forbidden in forbidden_spells[child]:
                    if f_forbidden >= child and f_child not in total_children:
                        total_children[f_child].append(child)
                        total_children[child].append(f_child)
                        total_children[f_child].append(forbidden_spell)
                        if len(forbidden_spells[f_child]) == 1:
                            if f_child == child:
                                adjacency_removed = True
                                break
                                # T(n*k) algorithm
                        heapq.heappush(max_spells, (child - f_child, f_child))
                        break
                if not adjacency_removed:
                    for f_child, f_forbidden in total_children[child] + total_children[forbidden_spell]:
                        max_spells.append((f_child - child, f_child))
    return len(heapq.merge(*max_spells))

