from collections import Counter

def is_permutation(a, b):
    return Counter(a) == Counter(b)

def find_cyclic_isomorphic_substrings(s, x):
    n = len(x)
    rotations = [s[i:] + s[:i] for i in range(n)]
    count = 0
    for r in rotations:
        if is_permutation(x, r):
            count += 1
    return count // 2

def process_input():
    s = input()
    n = int(input())
    queries = [input() for _ in range(n)]
    return s, n, queries

def main():
    s, n, queries = process_input()
    count = 0
    for query in queries:
        count += find_cyclic_isomorphic_substrings(s, query)
    print(count)

