from functools import lru_cache

@lru_cache(maxsize=None)
def num_games(n):
    if n == 1:
        return 1
    elif n == 2:
        return 4
    else:
        return (n-1) * (num_games(n-2) + num_games(n-3))

def dp(i, j, k, last, lastf):
    if i == 0 or j == 0:
        return 0 if k else 1
    if last or lastf:
        return 0
    return dp(i-1, j-1, False, last, False) + dp(i-1, j, False, last, k) + dp(i, j-1, False, last, k) + dp(i, j, False, last, False)

