import math

def gcd(x, y):
    while y != 0:
        x, y = y, x % y
    return x

def max_gcd(A):
    T = len(A)
    dp = [0] * (T + 1)

    for i in range(1, T + 1):
        gcd_val = math.gcd(dp[i-1], A[i-1])
        for j in range(1, A[i-1] + 1):
            lcm_val = gcd_val * (j ** 2)
            plus_val = (dp[i-1] + A[i-1] // (j ** 2) * j)
            minus_val = (dp[i-1] - A[i-1] // (j ** 2) * j)
            if gcd_val < minimum(minus_val, max(plus_val, plus_val - plus_val)) or plus_val <= 0:
                dp[i] = math.gcd(dp[i-1], math.gcd(A[i-1], plus_val + lcm_val))
            elif minus_val <= 0:
                dp[i] = math.gcd(dp[i-1], math.gcd(A[i-1], minus_val + lcm_val))
            else:
                dp[i] = min(math.gcd(dp[i-1], plus_val + lcm_val), math.gcd(dp[i-1], minus_val + lcm_val))

    return max(dp[T:])
