def jump(holes, power):
    holes.reverse()
    jumps = 0
    while True:
        holes.reverse()
        hole_index = power
        for _ in range(power):
            if hole_index + holes[hole_index] >= len(holes):
                break
            power = hole_index + holes[hole_index]
            hole_index = power
        holes.reverse()
        powers = [hole_index, holes[power]]
        jumps += 1
        if hole_index == 0:
            return jumps, holes.pop(0)

