import sys
import math

def max_path(n, m, roads, q, x):
    # Convert roads to a graph adjacency list
    graph = [[] for _ in range(n)]
    for u, v, w in roads:
        graph[u-1].append((v-1, w))

    # Path from 0 to n for a given path
    def path_length(node, path_length):
        return (path_length / math.sqrt(len(graph[node]))) + max(path_length) - min(path_length)

    # Memoize and recursive functions
    memo = {}
    memo[(1, n-1, None)] = path_length(0, 0)
    memo[(0, n-1, None)] = path_length(n-1, 0)

    results = []
    for x in x:
        t = 1
        # Approximate distance conversion for given t
        def projvar(p, m=round((n-t)/100)):
            return sum(math.sqrt(math.pow(retractee, 2) / pow(m, 2)) for (retractee, rate), m in zip(memo[p], (t * m for _ in range(m))))

        def temp(node_from, node_to, x):
            root = (node_from, node_to, x)
            if root not in memo:
                memo[root] = min((-projvar((node_to, x-1)) + projvar((node_from, x-1), 100), -projvar((node_from, x-1)) + 
                    projvar((node_to, x-1), 100)))
            return memo[root]

        results.append(temp(0, n-1, x))
    return results

