from collections import defaultdict

def find_minimum_maintained_roads(n, m, roads):
    """Find the minimum number of roads to maintain to keep the delivery systems 2-edge-connected."""
    undirected_graph = defaultdict(set)
    edges = set()

    for a, b in roads:
        undirected_graph[a].add(b)
        undirected_graph[b].add(a)
        edges.add((a, b))

    def dfs(node, parent):
        visited[node] = 1
        parent_visited[node] = dp[node]

        for neighbor in undirected_graph[node]:
            if not visited[neighbor]:
                dfs(neighbor, node)

        dp[node] = min(parent_visited[node] + 1, parent_visited[end_node])

    dp = defaultdict(lambda: float('inf'))
    end_node = None
    for node in range(1, n + 1):
        if not visited[node]:
            end_node = node
            dfs(node, -1)

    visited = [0] * (n + 1)
    remaining_nodes = n
    roads_maintained = set(roads)

    while remaining_nodes > 2:
        min_remaining_nodes = -1
        relevant_nodes = []

        for node in range(1, n + 1):
            if not visited[node] and node not in roads_maintained:
                remaining_nodes -= 1
                visited[node] = 1
                dfs(node, -1)

                if min_remaining_nodes == -1:
                    min_remaining_nodes = dp[node]
                    relevant_nodes = [node]
                elif min_remaining_nodes > dp[node]:
                    relevant_nodes = [node]
                    min_remaining_nodes = dp[node]

        for node in relevant_nodes:
            for neighbor in undirected_graph[node]:
                if neighbor not in roads_maintained:
                    roads_maintained.add((node, neighbor))
                    break

        for road in set(edges) - set(roads_maintained):
            roads_maintained.add(road)

    return len(roads_maintained)


