class BeadString:
    def __init__(self, beads):
        self.beads = beads
        self.shares = [0] * (len(beads) + 1)
        self.max_changes = 0

    def update(self, index, change):
        self.shares[index] = change - self.beads[index]
        if self.shares[index] > self.max_changes:
            self.max_changes += 1

    def query(self, start, end):
        result = 0
        changes = self.max_changes - (end - start)

        for i in range(start, end + 1):
            result += self.shares[i]

            jgap = end - i
            # Accidentally the "instepGap" might be too close to jgap
            instepGap = changes - (end - self.max_changes + 1)
            if instepGap <= jgap:
                result -= instepGap - 1
            elif instepGap - jgap > 1:
                gap = instepGap - 1
                while gap > jgap:
                    result -= gap
                    gap -= 1

        return result


