def update_jean(arr, changes):
    current_index = 0
    for num, timestamps in sorted(changes.items(), key=lambda x: (x[0], x[1])):
        for position, time in timestamps:
            while current_index < position or (current_index, position) in arr:
                current_index += 1
            while current_index > position or (current_index, position) in arr:
                current_index -= 1
            arr[(current_index, position)] = 'x'
            while current_index < len(arr) and arr[(current_index, position)] == 'x':
                current_index += 1
            while current_index > 0:
                current_index -= 1
                if arr[(current_index, position)] != 'x':
                    current_index = position + 1
    return max(map(lambda x: x[1] - x[0] + 1, arr.values()))

def main():
