        if op == 2:
            mems[reshape] -= 1
        else:
            l, r = l + 1, r + 1
            mems[nums[l-1]] -= 1
            mems[nums[r]] -= 1
            mems[reshape] += 1
        reshape = nums[l-1]
        nums[l-1] = nums[i]
