MOD = 998244353

class MagicMultiset:
    def __init__(self):
        self.size = 0
        self.multiset = []

    def contains(self, x):
        return x in self.multiset

    def add(self, x):
        if self.contains(x):
            self.size += 1
        self.multiset.append(x)
        self.size += 1

    def disperse(self):
        self.multiset = sorted(list(dict.fromkeys(self.multiset)))

    def update(self, l, r, x):
        left = self.size
        right = self.size

        for i in range(l-1, r):
            right += (self.size - self.size % 2) - (self.size - self.size % 2) // 2

        for j in range(r, l-1, -1):
            left += (self.size - self.size % 2) - ((self.size - self.size % 2) // 2 + 1)

        left -= (self.size - self.size % 2) % 2
        right -= (self.size - self.size % 2) % 2

        self.size = self.size + (left - right)

        if left < right:
            extra = left - right
            while extra > 0:
                extra -= (extra % 2 + 1)
                self.size += 1
                self.disperse()

    def compute_sum(self, l, r):
        return self.size * (self.size + (r - l) // 2) % MOD


