from collections import defaultdict

def are_isomorphic(s1, s2):
    mapping = defaultdict(str)
    for i in range(len(s1)):
        if s1[i] != s2[i]:
            if s1[i] in mapping and mapping[s1[i]] != s2[i]:
                return False
            if s2[i] in mapping.values():
                duplicate_char = list(mapping.values()).index(s2[i])
                if i == duplicate_char:
                    return False
            mapping[s1[i]] = s2[i]
    return True

def count_isomorphic_substrings(s, query_strings):
    substrings = defaultdict(int)
    for query in query_strings:
        count = 0
        start = 0
        end = len(s)
        while start < end:
            if are_isomorphic(s[start:end], query):
                count += substrings[(s[start:end], start, query)]
                substrings[(s[start:end], start, query)] += 1
                start += len(query) - 1
            else:
                end -= 1
        substrings[(s[start:end], start, query)] += 1
    return count

