        self.graph = [[] for _ in range(vertices)]

    def add_edge(self, v, u):
        self.graph[v].append(u)
        self.graph[u].append(v)

    def dfs_to_connect_components(self, u, dictionary):
        visited = [False] * self.V
        stack = [u]
        chain = 1
        while stack:
            current = stack.pop()
            if not visited[current]:
                visited[current] = True
                dictionary[str(chain)].append(current)
                stack.extend(self.graph[current][::-1])

    def find_components(self):
        connected_components = {}
        dictionary = {}
        for i in range(self.V):
            if not visited[i]:
                chain = 1
                dictionary[str(chain)] = []
                self.dfs_to_connect_components(i, dictionary)
                connected_components[str(chain)] = dictionary[str(chain)]
        return connected_components

    def get_minimum_graph(self):
        connected_components = self.find_components()
        min_graph = len(connected_components)
        for chain in connected_components:
            temp_graph = len(connected_components[chain])
            min_graph = min(min_graph, temp_graph)
        return min_graph

def find_minimum_maintenance(graph):
    return graph.get_minimum_graph()

