def restore_map(n: int, near_lists: list):
    """
    Restores the map of Treeland based on the given near lists of cities.
    """
    neighbors = [[] for _ in range(n)]
    visited = [False] * n

    for near in near_lists:
        k = near[0]
        start, end = near[-2], near[-1]
        start -= 1
        end -= 1

        for _ in range(k - len(neighbors[start])):
            neighbors[start].append(end)
            visited[end] = True
        neighbors[start].append(start)

    for i, near in enumerate(near_lists):
        k = near[0]
        start = near[-2]
        start -= 1
        for _ in range(k - len(neighbors[start])):
            neighbors[start].append(i)
        neighbors[start].append(start)

    distances = []
    for i, rels in enumerate(neighbors):
        dp = None
        for target in rels:
            if dp is None or dp > distances[i][target]:
                dp = distances[i][target]
        for target in rels:
            distances[i][target] = dp + 1

    # Find the cycle
    cycle = [-1] * n
    in_cycle = [False] * n
    def dfs(node):
        in_cycle[node] = True
        cycle[node] = len(cycle)
        for neighbor in neighbors[node]:
            if neighbor != cycle[node]:
                dfs(neighbor)
        return True

    for i in range(n):
        if not in_cycle[i]:
            dfs(i)

    tree_depth = []
    def dfs_2(node, current_depth):
        current_depth += 1
        for neighbor in neighbors[node]:
            if cycle[neighbor%n] != cycle[node]:
                dfs_2(neighbor%n, current_depth)

    for i in range(n):
        tree_depth.append(cycle[i])
        dfs_2(i, 0)

    # Construct the map from distance vector to depth vector
    for i in range(len(tree_depth) - 1, -1, -1):
        if distance[i] + 1 in neighbors:
            neighbors.push(distance[i] + 1)

    return neighbors

